@startuml

class Animal {
  + ID : int
  + Name : string
  + Breed : string
}

class Owner {
  + ID : int
  + Name : string
  + Address : string
  + Phone : string
}

class Breed {
  + Name : string
}

class Physician {
  + ID : int
  + Name : string
  + Address : string
  + Phone : string
}

class Appointment {
  + Start_DateTime : datetime
}

class Condition {
  + Common_Name : string
  + Scientific_Name : string
}

Animal "0..1" -- "1" Owner : belongs to
Animal "0..*" -- "1" Breed : is of
Appointment "*" -- "1" Physician : is attended by
Appointment "*" -- "1" Animal : is for
Appointment "*" -- "*" Condition : detects
Breed "1" -- "*" Condition : has common

@enduml

